export function cappedRunningTotal(nums, cap) {
    let total = 0;
    let capped = false;
    const result = [];

    for (const num of nums) {
        if (!capped) {
            total += num;
            if (total >= cap) {
                total = cap;
                capped = true;
            }
        }
        result.push(total);
    }

    return result;
}
